import java.util.LinkedList;

public class DoublyLinkedListExample {
    public static void main(String[] args) {
        // Java's built-in DLL implementation
        LinkedList<String> dll = new LinkedList<>(); 
        // Adding elements at the beginning and end
        dll.addFirst("Node1"); // Add to the beginning
        dll.addLast("Node2");  // Add to the end
        dll.addLast("Node3");  // Add another to the end

        // Traversing the list forward
        System.out.println("Forward Traversal:");
        for (String node : dll) {
            System.out.println(node);
        }

        // Removing elements
        dll.removeFirst(); // Remove from the beginning
        dll.removeLast();  // Remove from the end

        // Traversing the list again
        System.out.println("After Removals:");
        for (String node : dll) {
            System.out.println(node);
        }
    }
}

